public class AttendanceAnnouncer {static class Gym{int s;void info(StringBuilder b){b.append("Standard | Sessions: ").append(s).append(" | ");}}static class Premium extends Gym{String t;Premium(String t){this.t=t;}@Override void info(StringBuilder b){b.append("Premium | Trainer: ").append(t).append(" | Sessions: ").append(s).append(" | ");}}static String batchPrint(Gym[]a){StringBuilder b=new StringBuilder();for(Gym g:a){g.info(b);if(g instanceof Premium)b.append("[Trainer via downcast: ").append(((Premium)g).t).append("] | ");}return b.toString();}public static void main(String[]x){System.out.println(batchPrint(new Gym[]{new Gym(),new Premium("Coach Riya")}));}}
